import axios from 'axios';

// Backend API configuration
const API_BASE_URL = 'http://localhost:3000';
const API_VERSION = '/api/v1';

// Create axios instance for API calls
const API = axios.create({
  baseURL: `${API_BASE_URL}${API_VERSION}`,
  timeout: 15000,
  headers: {
    'Content-Type': 'application/json',
  },
});

// Request interceptor - adds auth token to every request
API.interceptors.request.use(
  (config) => {
    console.log(`📤 API Request: ${config.method?.toUpperCase()} ${config.url}`);
    const token = localStorage.getItem('auth_token');
    if (token) {
      config.headers.Authorization = `Bearer ${token}`;
    }
    return config;
  },
  (error) => {
    console.error('❌ Request error:', error);
    return Promise.reject(error);
  }
);

// Response interceptor - handles common errors
API.interceptors.response.use(
  (response) => {
    console.log(`📥 API Response: ${response.status} ${response.config.url}`);
    return response;
  },
  (error) => {
    if (error.code === 'ECONNABORTED') {
      console.error('⏰ Request timeout - server might be slow');
    } else if (error.message === 'Network Error') {
      console.error('🌐 Network Error - Make sure backend is running on port 3000');
      alert('Cannot connect to backend server. Please make sure it\'s running with "npm run dev" in the project2-api folder');
    } else if (error.response?.status === 401) {
      console.error('🔑 Unauthorized - Please login again');
      localStorage.removeItem('auth_token');
      localStorage.removeItem('project2_user');
      window.location.href = '/home.html';
    } else if (error.response?.status === 404) {
      console.error('🔍 Not Found - Endpoint does not exist');
    } else {
      console.error('❌ API Error:', error.response?.status, error.response?.data);
    }
    return Promise.reject(error);
  }
);

// ========== USERS API ==========
export const getUsers = (page = 1, limit = 5) => API.get(`/users?page=${page}&limit=${limit}`);
export const getUserById = (id) => API.get(`/users/${id}`);
export const createUser = (data) => API.post('/users', data);
export const updateUser = (id, data) => API.put(`/users/${id}`, data);
export const deleteUser = (id) => API.delete(`/users/${id}`);

// ========== AUTH API ==========
export const login = async (credentials) => {
  console.log('🔐 Login attempt for:', credentials.username);
  try {
    const response = await axios.post(`${API_BASE_URL}${API_VERSION}/auth/login`, credentials);
    console.log('✅ Login successful:', response.data.user?.username);

    if (response.data.token) {
      localStorage.setItem('auth_token', response.data.token);
      localStorage.setItem('project2_user', JSON.stringify(response.data.user));
    }
    return response;
  } catch (error) {
    console.error('❌ Login error:', error.response?.data?.error || error.message);
    throw error;
  }
};

export const register = async (userData) => {
  console.log('📝 Register attempt for:', userData.username);
  try {
    const response = await axios.post(`${API_BASE_URL}${API_VERSION}/auth/register`, userData);
    console.log('✅ Registration successful:', response.data.user?.username);

    if (response.data.token) {
      localStorage.setItem('auth_token', response.data.token);
      localStorage.setItem('project2_user', JSON.stringify(response.data.user));
    }
    return response;
  } catch (error) {
    console.error('❌ Register error:', error.response?.data?.error || error.message);
    throw error;
  }
};

export const getCurrentUser = async () => {
  try {
    const response = await API.get('/auth/me');
    return response;
  } catch (error) {
    console.error('Get current user error:', error);
    throw error;
  }
};

// ========== HEALTH CHECK ==========
export const getHealth = () => axios.get(`${API_BASE_URL}/health`);

// ========== CHAT API ==========
export const getChatUsers = () => API.get('/chat-users');
export const getMessages = (room = 'general') => API.get(`/messages/${room}`);

export default API;
